#include <algorithm>
#include <array>

struct Job { int id; bool done; };
std::array<Job, 3> jobs{{{1, true}, {2, false}, {3, false}}};
auto tail = std::remove_if(jobs.begin(), jobs.end(),
    [](const Job& job) { return job.done; });
// [jobs.begin(), tail) — незавершённые задания с id 2 и 3 в прежнем порядке.
// В array по-прежнему три объекта; состояния хвоста не предсказываем.
// У array нет erase: дальше обрабатываем только сохранённую часть диапазона.

std::vector<int> values{3, 6, 9};
auto it = std::lower_bound(values.begin(), values.end(), 5);
// it указывает на 6; ключа 5 в наборе нет
